  "input_artifacts": [
    "auth_fsm.v",
    "fault_model.json",
    "normal_trace.txt"
  ],
  "expected_output": "A vulnerability_report.json file identifying the vulnerable cycle and the critical state/result signals.",
  "metrics": [
    {
      "name": "leakage_detection_accuracy",
      "description": "Proportion of correctly identified vulnerable registers and cycles out of the total ground truth set.",
      "direction": "maximize"
    },
    {
      "name": "fault_coverage",
      "description": "Whether the reported vulnerability covers the critical fault injection point that leads to unauthorized access.",
      "direction": "maximize"
    },
    {
      "name": "hardening_precision",
      "description": "Precision of the hardening suggestions derived from the vulnerability report, measured as the ratio of correct suggestions to total suggestions.",
      "direction": "maximize"
    }
  ]
}

module auth_fsm (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  password,
    output reg         access_granted
);

    // State encoding
    localparam IDLE    = 3'd0;
    localparam COMPARE = 3'd1;
    localparam DECIDE  = 3'd2;
    localparam GRANT   = 3'd3;
    localparam DENY    = 3'd4;

    // Stored password (hardcoded for simplicity)
    localparam [7:0] STORED_PASSWORD = 8'hA5;

    // Registers
    reg [2:0] state_q;
    reg       auth_result_q;

    // Next-state logic
    reg [2:0] state_next;
    reg       auth_result_next;

    always @* begin
        // Defaults
        state_next = state_q;
        auth_result_next = auth_result_q;

        case (state_q)
            IDLE: begin
                state_next = COMPARE;
                auth_result_next = 1'b0;
            end

            COMPARE: begin
                if (password == STORED_PASSWORD)
                    auth_result_next = 1'b1;
                else
                    auth_result_next = 1'b0;
                state_next = DECIDE;
            end

            DECIDE: begin
                if (auth_result_q)
                    state_next = GRANT;
                else
                    state_next = DENY;
                // auth_result_next is not updated here; it retains its value
            end

            GRANT: begin
                state_next = IDLE;
                auth_result_next = 1'b0;
            end

            DENY: begin
                state_next = IDLE;
                auth_result_next = 1'b0;
            end

            default: begin
                state_next = IDLE;
                auth_result_next = 1'b0;
            end
        endcase
    end

    // Sequential update
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_q <= IDLE;
            auth_result_q <= 1'b0;
        end else begin
            state_q <= state_next;
            auth_result_q <= auth_result_next;
        end
    end

    // Output assignment
    always @* begin
        access_granted = (state_q == GRANT);
    end

endmodule

{
  "fault_type": "clock_glitch",
  "description": "A single narrow clock pulse is injected during a chosen clock cycle, causing exactly one register update to be skipped while all combinational logic continues to evaluate normally.",
  "capabilities": {
    "target": "any single register in the design",
    "effect": "the targeted register retains its previous value for that cycle; all other registers update as usual",
    "injection_timing": "attacker can choose any clock cycle to inject the glitch"
  },
  "assumptions": [
    "The glitch does not affect combinational logic evaluation.",
    "Only one register update is skipped per injection.",
    "The attacker can observe the system's output (access_granted) to determine success."
  ]
}
